  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// -------------------------------------------------------------\n// ENUMS\n// -------------------------------------------------------------\nenum Role {\n  USER\n  ADMIN\n}\n\nenum UserStatus {\n  ACTIVE\n  LOCKED\n}\n\nenum TransactionType {\n  INCOME\n  EXPENSE\n}\n\nenum MessageRole {\n  user\n  assistant\n}\n\n// -------------------------------------------------------------\n// 1. USER & AUTH MODELS\n// -------------------------------------------------------------\nmodel User {\n  id            String     @id @default(uuid()) @db.Uuid\n  fullName      String\n  email         String     @unique\n  passwordHash  String\n  avatarUrl     String?\n  role          Role       @default(USER)\n  status        UserStatus @default(ACTIVE)\n  currency      String     @default(\"VND\")\n  emailVerified Boolean    @default(false)\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n\n  // Relations\n  refreshTokens       RefreshToken[]\n  passwordResetTokens PasswordResetToken[]\n  wallets             Wallet[]\n  categories          Category[]\n  transactions        Transaction[]\n  budgets             Budget[]\n  savingGoals         SavingGoal[]\n  notifications       Notification[]\n  chatSessions        ChatSession[]\n  auditLogs           AuditLog[]\n\n  @@index([email])\n  @@index([role, status])\n  @@map(\"users\")\n}\n\nmodel RefreshToken {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String   @db.Uuid\n  tokenHash String   @unique\n  expiresAt DateTime\n  revoked   Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel PasswordResetToken {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String   @db.Uuid\n  tokenHash String   @unique\n  expiresAt DateTime\n  used      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"password_reset_tokens\")\n}\n\n// -------------------------------------------------------------\n// 2. FINANCE MODELS (Category, Wallet, Transaction, Budget, SavingGoal)\n// -------------------------------------------------------------\nmodel Category {\n  id        String          @id @default(uuid()) @db.Uuid\n  name      String\n  icon      String // Lucide icon name, e.g. \"Utensils\", \"Bus\", \"Coffee\"\n  color     String // Hex or token color\n  type      TransactionType\n  isDefault Boolean         @default(false)\n  userId    String?         @db.Uuid // null = system default category, non-null = user custom\n  createdAt DateTime        @default(now())\n  updatedAt DateTime        @updatedAt\n\n  user         User?         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  transactions Transaction[]\n  budgets      Budget[]\n\n  @@index([userId])\n  @@index([type])\n  @@map(\"categories\")\n}\n\nmodel Wallet {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String   @db.Uuid\n  name      String\n  balance   Decimal  @default(0.00) @db.Decimal(15, 2)\n  icon      String   @default(\"Wallet\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  transactions Transaction[]\n\n  @@index([userId])\n  @@map(\"wallets\")\n}\n\nmodel Transaction {\n  id         String          @id @default(uuid()) @db.Uuid\n  userId     String          @db.Uuid\n  categoryId String          @db.Uuid\n  walletId   String          @db.Uuid\n  type       TransactionType\n  amount     Decimal         @db.Decimal(15, 2)\n  note       String?\n  date       DateTime        @default(now())\n  createdAt  DateTime        @default(now())\n  updatedAt  DateTime        @updatedAt\n\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  category Category @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n  wallet   Wallet   @relation(fields: [walletId], references: [id], onDelete: Cascade)\n\n  @@index([userId, date])\n  @@index([categoryId])\n  @@index([walletId])\n  @@map(\"transactions\")\n}\n\nmodel Budget {\n  id             String   @id @default(uuid()) @db.Uuid\n  userId         String   @db.Uuid\n  categoryId     String?  @db.Uuid // null = total overall monthly budget\n  amount         Decimal  @db.Decimal(15, 2)\n  month          Int // 1-12\n  year           Int // e.g. 2026\n  alertThreshold Int      @default(80) // Alert user when expense reaches 80%\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  user     User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  category Category? @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, categoryId, month, year])\n  @@index([userId, month, year])\n  @@map(\"budgets\")\n}\n\nmodel SavingGoal {\n  id            String    @id @default(uuid()) @db.Uuid\n  userId        String    @db.Uuid\n  title         String\n  targetAmount  Decimal   @db.Decimal(15, 2)\n  currentAmount Decimal   @default(0.00) @db.Decimal(15, 2)\n  deadline      DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"saving_goals\")\n}\n\n// -------------------------------------------------------------\n// 3. NOTIFICATION & SYSTEM MODELS\n// -------------------------------------------------------------\nmodel Notification {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String?  @db.Uuid // null = broadcast to all users\n  title     String\n  message   String\n  type      String   @default(\"INFO\") // INFO, WARNING, BUDGET_ALERT, SYSTEM\n  isRead    Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, isRead])\n  @@map(\"notifications\")\n}\n\n// -------------------------------------------------------------\n// 4. AI CHATBOT MODELS\n// -------------------------------------------------------------\nmodel ChatSession {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String   @db.Uuid\n  title     String   @default(\"Phiên tư vấn mới\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user     User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  messages ChatMessage[]\n\n  @@index([userId])\n  @@map(\"chat_sessions\")\n}\n\nmodel ChatMessage {\n  id        String      @id @default(uuid()) @db.Uuid\n  sessionId String      @db.Uuid\n  role      MessageRole\n  content   String      @db.Text\n  createdAt DateTime    @default(now())\n\n  session ChatSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  @@index([sessionId, createdAt])\n  @@map(\"chat_messages\")\n}\n\n// -------------------------------------------------------------\n// 5. AUDIT LOG (ADMIN)\n// -------------------------------------------------------------\nmodel AuditLog {\n  id        String   @id @default(uuid()) @db.Uuid\n  adminId   String   @db.Uuid\n  action    String // e.g. \"USER_LOCK\", \"CATEGORY_UPDATE\", \"BROADCAST_NOTIFICATION\"\n  targetId  String?\n  createdAt DateTime @default(now())\n\n  admin User @relation(fields: [adminId], references: [id], onDelete: Cascade)\n\n  @@index([adminId])\n  @@index([action, createdAt])\n  @@map(\"audit_logs\")\n}\n",
